	@Inject
	public DecisionmakingGrammarAccess(GrammarProvider grammarProvider,
			TerminalsGrammarAccess gaTerminals) {
		this.grammar = internalFindGrammar(grammarProvider);
		this.gaTerminals = gaTerminals;
		this.pGroupDecisionSession = new GroupDecisionSessionElements();
		this.pLibDesRun = new LibDesRunElements();
		this.pImport = new ImportElements();
		this.pLibrary = new LibraryElements();
		this.pStrategy = new StrategyElements();
		this.pStrategyPredefined = new StrategyPredefinedElements();
		this.pRule = new RuleElements();
		this.pPredefinedRule = new PredefinedRuleElements();
		this.pStrategyDecisionRule = new StrategyDecisionRuleElements();
		this.pPredefinedDecisionRule = new PredefinedDecisionRuleElements();
		this.pStrategyAlgorithm = new StrategyAlgorithmElements();
		this.pDecisionRule = new DecisionRuleElements();
		this.pAlgorithm = new AlgorithmElements();
		this.pDesignTime = new DesignTimeElements();
		this.pDecisionSupport = new DecisionSupportElements();
		this.pStrat = new StratElements();
		this.pRunTime = new RunTimeElements();
		this.pSADDResult = new SADDResultElements();
		this.pAlternativePreference = new AlternativePreferenceElements();
		this.pPreference = new PreferenceElements();
		this.ePreferenceIndicationKind = new PreferenceIndicationKindElements();
		this.pQualifiedName = new QualifiedNameElements();
		this.eBOOLEAN = new BOOLEANElements();
	}
	
	protected Grammar internalFindGrammar(GrammarProvider grammarProvider) {
		Grammar grammar = grammarProvider.getGrammar(this);
		while (grammar != null) {
			if ("xtext.Decisionmaking".equals(grammar.getName())) {
				return grammar;
			}
			List<Grammar> grammars = grammar.getUsedGrammars();
			if (!grammars.isEmpty()) {
				grammar = grammars.iterator().next();
			} else {
				return null;
			}
		}
		return grammar;
	}
	
	@Override
	public Grammar getGrammar() {
		return grammar;
	}
	
	
	public TerminalsGrammarAccess getTerminalsGrammarAccess() {
		return gaTerminals;
	}

	
